export enum QuarterKey {
  Q1 = 'Q1',
  Q2 = 'Q2',
  Q3 = 'Q3',
  Q4 = 'Q4',
}

export enum HalfKey {
  H1 = 'H1',
  H2 = 'H2',
}

type MonthToken =
  | '01'
  | '02'
  | '03'
  | '04'
  | '05'
  | '06'
  | '07'
  | '08'
  | '09'
  | '10'
  | '11'
  | '12';

export type YearMonth = `${number}-${MonthToken}`;

export interface YearMonthParts {
  year: number;
  month: number;
}

export interface MonthRange {
  startMonthIndex: number;
  endMonthIndex: number;
}

export const MONTH_NAMES_SHORT = [
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
] as const;

export const QUARTER_MONTH_RANGES: Readonly<Record<QuarterKey, MonthRange>> = {
  [QuarterKey.Q1]: { startMonthIndex: 0, endMonthIndex: 2 },
  [QuarterKey.Q2]: { startMonthIndex: 3, endMonthIndex: 5 },
  [QuarterKey.Q3]: { startMonthIndex: 6, endMonthIndex: 8 },
  [QuarterKey.Q4]: { startMonthIndex: 9, endMonthIndex: 11 },
};

export const HALF_MONTH_RANGES: Readonly<Record<HalfKey, MonthRange>> = {
  [HalfKey.H1]: { startMonthIndex: 0, endMonthIndex: 5 },
  [HalfKey.H2]: { startMonthIndex: 6, endMonthIndex: 11 },
};

const parseYearAndMonth = (
  yearToken: string,
  monthToken: string,
): YearMonthParts | null => {
  const year = Number(yearToken);
  const month = Number(monthToken);
  return month >= 1 && month <= 12 ? { year, month } : null;
};

export const parseCutoffDate = (
  cutoffDate: string | null | undefined,
): YearMonthParts | null => {
  if (!cutoffDate) return null;
  const match = /^(\d{4})-(\d{2})(?:-(\d{2}))?$/.exec(cutoffDate);
  if (!match) return null;
  const day = match[3] ? Number(match[3]) : null;
  if (day !== null && (day < 1 || day > 31)) return null;
  return parseYearAndMonth(match[1], match[2]);
};

export const parseYearMonth = (value: string): YearMonthParts | null => {
  const match = /^(\d{4})-(\d{2})$/.exec(value);
  return match ? parseYearAndMonth(match[1], match[2]) : null;
};

export const isYearMonth = (value: unknown): value is YearMonth =>
  typeof value === 'string' && parseYearMonth(value) !== null;

export const isQuarterKey = (value: unknown): value is QuarterKey =>
  Object.values(QuarterKey).includes(value as QuarterKey);

export const isHalfKey = (value: unknown): value is HalfKey =>
  Object.values(HalfKey).includes(value as HalfKey);

export const toYearMonth = (monthIndex: number, year: number): YearMonth =>
  `${year}-${String(monthIndex + 1).padStart(2, '0')}` as YearMonth;

export const shiftYearMonth = (
  year: number,
  month: number,
  offset: number,
): YearMonthParts => {
  const zeroBasedMonth = month - 1 + offset;
  const shiftedYear = year + Math.floor(zeroBasedMonth / 12);
  const shiftedMonth = ((zeroBasedMonth % 12) + 12) % 12;
  return { year: shiftedYear, month: shiftedMonth + 1 };
};
